// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }

    function testFuzz_property(uint256 amount, bool useReverter) public {
        vm.assume(amount > 0);
        vm.deal(address(c), 1 ether);
        address victim;
        if (useReverter) {
            victim = address(new Reverter());
        } else {
            victim = address(new Acceptor());
        }

        uint256 before = address(c).balance;

        bool ok;
        try c.sendTo(victim, amount) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(address(c).balance == before - amount);
        } else {
            assertTrue(address(c).balance == before);
        }
    }
}

contract Reverter {
    fallback() external payable {
        revert("revert");
    }
    receive() external payable {
        revert("revert");
    }
}

contract Acceptor {
    receive() external payable {}
}
